121	          "pratika_iast": "sa",
122	          "matches_verse": false,
123	          "content_containment": 0.778,
124	          "content_anchor": true
125	        }
126	      }
127	    },
128	    {
129	      "verse_id": "5.46.5",
130	      "sarga": 46,
131	      "verse": "5",
132	      "ambiguous_marker": false,
133	      "sanskrit_iast": "yattaiś ca khalu bhāvyaṃ syāt tam āsādya vanālayam । karma cāpi samādheyaṃ deśakālāvirodhitam ॥5॥",
134	      "leonov_ru": "Должно соблюдать осторожность, приблизившись к тому лесному жителю, И действия, которые будут предприняты [вами], не должны расходиться с местом и временем.",
135	      "commentary": {
136	        "tilaka": "यत्तैः सावसानैः । किं चात्र देशकालविरोधि कर्म न कार्यमित्याह-- देशकालाविरोधितं तदविरुद्धम् । तदुचितमिति यावत् । समाधेयं कार्यम्",
137	        "bhusana": "यत्तैश्च खलु भाव्यं स्यात्तमासाद्य वनालयम् ।\n\nकर्म चापि समाधेयं देशकालविरोधिनम्\nतमेवाह यत्तैरित्यादिना । यत्तैः यतमानैः । अप्रमत्तैरिति यावत् । यतेः कर्तरि क्तः । समाधेयं परिहर्तव्यम् । देशकालविरोधिनं देशकालविरोधीत्यर्थः",
138	        "siromani": "यत्नैरिति । वनालयं वानरमासाद्य यत्नैरतिप्रयत्नविशिष्टैर्भवद्भिर्भाव्यं स्यात् । देशकालाविरोधितं देशाद्यनुरोधीत्यर्थः । कर्म समाधेयं च"
139	      },
140	      "pratika_check": {
141	        "tilaka": {
142	          "pratika_iast": "yattaih savasanaih",
143	          "matches_verse": false,
144	          "content_containment": 0.25,
145	          "content_anchor": true
146	        },
147	        "bhusana": {
148	          "pratika_iast": "yattaisca khalu bhavyan syattanasadya",
149	          "matches_verse": true
150	        },
151	        "siromani": {
152	          "pratika_iast": "yatnairiti",
153	          "matches_verse": false,
154	          "content_containment": 0.5,
155	          "content_anchor": true
